  stop: ['Стоп-лосс (стоп)', 'Заранее выбранный уровень, при котором мы признаём ошибку и закрываем убыточную позицию, чтобы убыток не рос бесконечно.'],
  max_hold: ['Предельное удержание', 'Максимальное число дней в сделке. Если за это время спред не вернулся, закрываем позицию принудительно.'],
  signal: ['Сигнал', 'Момент, когда правила стратегии говорят «открыть» или «закрыть» позицию.'],
  bar: ['Бар (свеча, день)', 'Один период времени с одной итоговой ценой. В учебнике один бар — один торговый день, цена — по закрытию.'],
  cost: ['Издержки', 'Всё, что мы платим за сделки: комиссии биржи и брокера и проскальзывание. Каждая сделка слегка уменьшает результат.'],
  commission: ['Комиссия', 'Плата бирже и брокеру за каждую сделку. Берётся независимо от того, выиграли вы или проиграли.'],
